import{_ as a,o as n,a as p,b as c}from"./app.BGziXukh.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/programming_guide"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/aclnn_operator_development"},{"text":"附录","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/appendix"},{"text":"CMake函数参考","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/cmake_function_reference"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/cmake_function_reference.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/cmake_function_reference.md","outlineHeaders":[{"level":2,"title":"概述","slug":"概述","link":"#概述"},{"level":2,"title":"函数一览","slug":"函数一览","link":"#函数一览"},{"level":2,"title":"Package类函数","slug":"Package类函数","link":"#Package类函数"},{"level":3,"title":"npu_op_package","slug":"npu_op_package","link":"#npu_op_package"},{"level":3,"title":"npu_op_package_add","slug":"npu_op_package_add","link":"#npu_op_package_add"},{"level":2,"title":"Library类函数","slug":"Library类函数","link":"#Library类函数"},{"level":3,"title":"npu_op_library","slug":"npu_op_library","link":"#npu_op_library"},{"level":3,"title":"npu_op_kernel_library","slug":"npu_op_kernel_library","link":"#npu_op_kernel_library"},{"level":3,"title":"npu_op_kernel_options","slug":"npu_op_kernel_options","link":"#npu_op_kernel_options"},{"level":3,"title":"npu_op_kernel_sources","slug":"npu_op_kernel_sources","link":"#npu_op_kernel_sources"},{"level":3,"title":"npu_op_device_tiling_library","slug":"npu_op_device_tiling_library","link":"#npu_op_device_tiling_library"},{"level":2,"title":"其他","slug":"其他","link":"#其他"},{"level":3,"title":"npu_op_code_gen","slug":"npu_op_code_gen","link":"#npu_op_code_gen"},{"level":2,"title":"相关文档","slug":"相关文档","link":"#相关文档"}],"lastUpdated":1794274482000}'),e={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/cmake_function_reference.md"};function l(o,s,d,t,i,_){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>CMake函数参考</h1><p>本文是参考内容，整理算子工程编译过程涉及的CMake函数接口，供需要深入了解编译机制的高级开发者查阅。</p><h2 id="概述">概述<a class="header-anchor" href="#概述">​</a></h2><p>自定义算子工程的CMakeLists.txt由开发者直接编写。为便于开发者组织编译脚本，CANN软件包中将算子工程编译所需的CMake脚本打包为CMake modules，开发者可通过<code>find_package(ASC REQUIRED)</code>查找并使用这些函数。</p><p>本文说明算子工程编译过程中使用的8个CMake函数，按用途分为<strong>Package类</strong>、<strong>Library类</strong>、<strong>其他</strong>三类。</p><h2 id="函数一览">函数一览<a class="header-anchor" href="#函数一览">​</a></h2><table><thead><tr><th>分类</th><th>函数</th><th>功能</th></tr></thead><tbody><tr><td>Package</td><td><code>npu_op_package</code></td><td>创建一个package。</td></tr><tr><td>Package</td><td><code>npu_op_package_add</code></td><td>将目标或文件添加到package中。</td></tr><tr><td>Library</td><td><code>npu_op_library</code></td><td>创建Host侧库。</td></tr><tr><td>Library</td><td><code>npu_op_kernel_library</code></td><td>创建核函数（Kernel）侧库。</td></tr><tr><td>Library</td><td><code>npu_op_kernel_options</code></td><td>添加核函数（Kernel）目标编译选项。</td></tr><tr><td>Library</td><td><code>npu_op_kernel_sources</code></td><td>描述核函数（Kernel）目标的源码信息。</td></tr><tr><td>Library</td><td><code>npu_op_device_tiling_library</code></td><td>创建Device侧Tiling库。</td></tr><tr><td>其他</td><td><code>npu_op_code_gen</code></td><td>执行代码生成过程，生成aclnn单算子调用代码和入图所需的原型定义代码。</td></tr></tbody></table><hr><h2 id="Package类函数">Package类函数<a class="header-anchor" href="#Package类函数">​</a></h2><h3 id="npu_op_package">npu_op_package<a class="header-anchor" href="#npu_op_package">​</a></h3><p>创建一个package。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_package</span><span class="p">(</span><span class="s">&lt;package_name&gt;</span>
<span class="w">    </span><span class="s">TYPE</span><span class="w"> </span><span class="s">&lt;RUN|SHARED|STATIC&gt;</span>
<span class="w">    </span><span class="s">[CONFIG</span><span class="w"> </span><span class="s">&lt;key&gt;</span><span class="w"> </span><span class="s">&lt;value&gt;</span><span class="w"> </span><span class="s">...]</span>
<span class="p">)</span>
</code></pre></div><p><strong>参数说明：</strong></p><ul><li><code>&lt;package_name&gt;</code>（必选）：package的名称。</li><li><code>TYPE &lt;type&gt;</code>（必选）：package的类型，取值为<code>RUN</code>、<code>SHARED</code>、<code>STATIC</code>。分别对应算子run包形式、算子动态库形式与算子静态库形式。</li><li><code>CONFIG &lt;key&gt; &lt;value&gt; ...</code>（可选）：用于配置package的内容和输出位置。各配置项以“参数名 参数值”的形式写在<code>CONFIG</code>之后，支持以下选项： <ul><li><code>ENABLE_SOURCE_PACKAGE &lt;value&gt;</code>：是否将源码打包到package中，默认使用工程中<code>ENABLE_SOURCE_PACKAGE</code>的值（未设置时为<code>True</code>）。</li><li><code>ENABLE_BINARY_PACKAGE &lt;value&gt;</code>：是否将二进制文件打包到package中，默认使用工程中<code>ENABLE_BINARY_PACKAGE</code>的值（未设置时为<code>True</code>）。<code>SHARED</code>和<code>STATIC</code>模式下，必须开启此选项。</li><li><code>INSTALL_PATH &lt;path&gt;</code>：指定构建产物的输出路径，例如生成的run包存放位置。默认使用<code>ASCENDC_INSTALL_PREFIX</code>：通常为构建目录；设置了<code>CMAKE_INSTALL_PREFIX</code>时，则使用该路径。</li><li><code>ENABLE_CPACK &lt;value&gt;</code>：是否生成run包，仅用于<code>RUN</code>模式，默认为<code>True</code>。设置为<code>False</code>后，执行<code>install</code>目标会将目录和文件安装到<code>INSTALL_PATH</code>下，不再生成run包。</li><li><code>ENABLE_DEFAULT_PACKAGE_NAME_RULE &lt;value&gt;</code>：默认为<code>True</code>，<code>RUN</code>模式下安装包默认命名为<code>custom_opp_&lt;os&gt;_&lt;arch&gt;.run</code>；设置为<code>False</code>时命名为<code>&lt;package_name&gt;.run</code>。</li><li><code>VENDOR_NAME &lt;name&gt;</code>：算子包的厂商名称，默认为<code>&lt;package_name&gt;</code>，用于确定包内的<code>vendors/&lt;name&gt;</code>目录名。</li></ul></li></ul><p><strong>示例：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">set</span><span class="p">(</span><span class="s">package_name</span><span class="w"> </span><span class="o">\${</span><span class="nv">vendor_name</span><span class="o">}</span><span class="p">)</span>
<span class="nb">npu_op_package</span><span class="p">(</span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span><span class="w">                     </span><span class="c"># package name</span>
<span class="w">    </span><span class="s">TYPE</span><span class="w"> </span><span class="s">RUN</span><span class="w">                                       </span><span class="c">#指定编译产物形态，[RUN|STATIC|SHARED]</span>
<span class="w">    </span><span class="s">CONFIG</span>
<span class="w">        </span><span class="s">ENABLE_SOURCE_PACKAGE</span><span class="w"> </span><span class="s">True</span><span class="w">                 </span><span class="c">#是否将源码打包到package中</span>
<span class="w">        </span><span class="s">ENABLE_BINARY_PACKAGE</span><span class="w"> </span><span class="s">True</span><span class="w">                 </span><span class="c">#是否编译核函数（Kernel）二进制</span>
<span class="w">        </span><span class="s">INSTALL_PATH</span><span class="w"> </span><span class="o">\${</span><span class="nv">CMAKE_BINARY_DIR</span><span class="o">}</span><span class="s">/</span><span class="w">          </span><span class="c"># package的安装位置</span>
<span class="p">)</span>
</code></pre></div><h3 id="npu_op_package_add">npu_op_package_add<a class="header-anchor" href="#npu_op_package_add">​</a></h3><p>将目标或文件添加到package中。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c"># 添加目标</span>
<span class="nb">npu_op_package_add</span><span class="p">(</span><span class="s">&lt;package_name&gt;</span><span class="w"> </span><span class="s">LIBRARY</span><span class="w"> </span><span class="s">&lt;target_name1&gt;</span><span class="w"> </span><span class="s">[&lt;target_name2&gt;...]</span>
<span class="w">    </span><span class="s">[PACKAGE_PATH</span><span class="w"> </span><span class="s">&lt;pkg_path&gt;]</span><span class="p">)</span>
<span class="c"># 添加文件，仅给run包模式使用</span>
<span class="nb">npu_op_package_add</span><span class="p">(</span><span class="s">&lt;package_name&gt;</span><span class="w"> </span><span class="s">FILES</span><span class="w"> </span><span class="s">&lt;file_name1&gt;</span><span class="w"> </span><span class="s">[&lt;file_name2&gt;...]</span><span class="w"> </span><span class="s">TYPE</span><span class="w"> </span><span class="s">&lt;ACLNN|GRAPH&gt;</span><span class="p">)</span>
<span class="nb">npu_op_package_add</span><span class="p">(</span><span class="s">&lt;package_name&gt;</span><span class="w"> </span><span class="s">FILES</span><span class="w"> </span><span class="s">&lt;file_name1&gt;</span><span class="w"> </span><span class="s">[&lt;file_name2&gt;...]</span><span class="w"> </span><span class="s">PACKAGE_PATH</span><span class="w"> </span><span class="s">&lt;pkg_path&gt;</span><span class="p">)</span>
</code></pre></div><p><strong>参数说明：</strong></p><ul><li><code>&lt;package_name&gt;</code>（必选）：package的名称。</li></ul><p><code>LIBRARY</code>和<code>FILES</code>必须选择一个，不能同时使用。</p><ul><li><code>LIBRARY &lt;target_name1&gt; [&lt;target_name2&gt;...]</code>：指定需要添加到package中的库目标。添加前，需先通过对应的<code>npu_op_*_library</code>函数定义该目标。</li><li><code>FILES &lt;file_name1&gt; [&lt;file_name2&gt;...]</code>：指定需要添加到package中的文件，仅支持<code>RUN</code>模式。添加文件时，还需通过<code>TYPE</code>或<code>PACKAGE_PATH</code>指定包内位置，否则文件不会被安装。</li><li><code>[TYPE &lt;target_type&gt;]</code>（可选）：指定文件类型，将文件安装到对应的目录中，取值为<code>ACLNN</code>、<code>GRAPH</code>。配置为<code>ACLNN</code>，会将文件打包至run包目录下aclnn单算子调用头文件所在目录；配置为<code>GRAPH</code>，会将文件打包至run包目录下入图原型定义头文件目录下。</li><li><code>[PACKAGE_PATH &lt;pkg_path&gt;]</code>（可选）：指定文件或Host侧库在run包中的存放位置。与<code>npu_op_package</code>的<code>INSTALL_PATH</code>不同，此参数设置的是包内目录。 <ul><li>添加文件（<code>FILES</code>）时：填写相对于<code>packages/vendors/&lt;vendor_name&gt;/</code>的路径，例如<code>include</code>。<code>PACKAGE_PATH</code>与<code>TYPE</code>只能选择一个。</li><li>添加Host侧库（<code>LIBRARY</code>）时：填写相对于包根目录的路径，例如<code>packages/vendors/customize/op_api</code>，用于替换该类库的默认目录。</li></ul></li></ul><p>同一次调用中，每种库类型只处理最后一个目标。例如，同时传入两个<code>TILING</code>目标时，只处理后一个。因此，多个同类库应分次添加；同时传入多个核函数库还会产生警告。</p><p><strong>示例：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c"># 添加Host侧相关library</span>
<span class="nb">npu_op_package_add</span><span class="p">(</span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span>
<span class="w">    </span><span class="s">LIBRARY</span>
<span class="w">        </span><span class="s">cust_optiling</span>
<span class="w">        </span><span class="s">cust_opapi</span>
<span class="w">        </span><span class="s">cust_op_proto</span>
<span class="p">)</span>

<span class="c"># 添加核函数（Kernel）侧相关library</span>
<span class="nb">npu_op_package_add</span><span class="p">(</span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span>
<span class="w">    </span><span class="s">LIBRARY</span><span class="w"> </span><span class="s">ascendc_kernels</span>
<span class="p">)</span>
</code></pre></div><hr><h2 id="Library类函数">Library类函数<a class="header-anchor" href="#Library类函数">​</a></h2><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>本节<code>npu_op_kernel_options</code>/<code>npu_op_kernel_sources</code>的<code>SOC_SERIES</code>/<code>COMPUTE_UNIT</code>参数，与<a href="../compilation_and_deployment/basic_process.html#compile-configuration">编译配置</a>中工程级的<code>ASCEND_SOC_SERIES</code>/<code>ASCEND_COMPUTE_UNIT</code>变量是两个不同层次的概念，参数名相同但含义不同，容易混淆：</p></div><table><thead><tr><th>层次</th><th>配置项</th><th>作用</th></tr></thead><tbody><tr><td>全局</td><td><code>ASCEND_SOC_SERIES</code>（或<code>ASCEND_COMPUTE_UNIT</code>），工程级CMake变量</td><td>决定整个工程为哪些AI处理器系列构建产物</td></tr><tr><td>细粒度</td><td>本节函数的<code>SOC_SERIES</code>/<code>COMPUTE_UNIT</code>参数</td><td>在全局已配置的范围内，这一条编译选项或核函数（Kernel）源码具体用在哪些型号上</td></tr></tbody></table><h3 id="npu_op_library">npu_op_library<a class="header-anchor" href="#npu_op_library">​</a></h3><p>创建Host侧库。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_library</span><span class="p">(</span><span class="s">&lt;library_name&gt;</span><span class="w"> </span><span class="s">&lt;library_type&gt;</span><span class="w"> </span><span class="s">&lt;files&gt;...</span>
<span class="w">    </span><span class="s">[CONFIG</span><span class="w"> </span><span class="s">&lt;key&gt;</span><span class="w"> </span><span class="s">&lt;value&gt;</span><span class="w"> </span><span class="s">...]</span><span class="p">)</span>
</code></pre></div><p><strong>参数说明：</strong></p><ul><li><code>&lt;library_name&gt;</code>（必选）：Host侧库的名称。</li><li><code>&lt;library_type&gt;</code>（必选）：Host库的类型，可选值为<code>TILING</code>、<code>ACLNN</code>、<code>GRAPH</code>、<code>TF_PLUGIN</code>、<code>ONNX_PLUGIN</code>。 <ul><li><code>TILING</code>：Tiling相关库。</li><li><code>ACLNN</code>：aclnn单算子调用库。</li><li><code>GRAPH</code>：算子入图所需的算子原型库。</li><li><code>TF_PLUGIN</code>：TensorFlow框架适配相关库。</li><li><code>ONNX_PLUGIN</code>：ONNX框架适配相关库。</li></ul></li><li><code>&lt;files&gt;...</code>（必选）：设置参与编译的源文件，相对路径以当前源码目录为基准。</li><li><code>CONFIG &lt;key&gt; &lt;value&gt; ...</code>（可选）：用于配置run包中Host侧动态库的名称，支持以下开关，参数值可填写<code>True</code>或<code>False</code>。开启后，动态库使用<code>&lt;library_name&gt;</code>作为库名。 <ul><li><code>SET_OPAPI_NAME</code>：用于<code>ACLNN</code>库，默认库名为<code>cust_opapi</code>。</li><li><code>SET_TILING_NAME</code>：用于<code>TILING</code>库，默认库名为<code>cust_opmaster_rt2.0</code>。</li><li><code>SET_OP_PROTO_NAME</code>：用于<code>GRAPH</code>库，默认库名为<code>cust_opsproto_rt2.0</code>。</li></ul></li></ul><p>修改Tiling库或原型库的名称时，CMake会提示兼容性警告。通常保留默认名称即可。</p><p><code>&lt;library_type&gt;</code>需使用上述大写形式。<code>ACLNN</code>、<code>TILING</code>和<code>GRAPH</code>先配置目标文件的编译，再由<code>npu_op_package_add</code>配置最终库的链接；<code>TF_PLUGIN</code>和<code>ONNX_PLUGIN</code>直接配置动态库的编译和链接，默认库名分别为<code>cust_tf_parsers</code>和<code>cust_onnx_parsers</code>。上述函数只配置构建任务，实际编译和链接在执行构建命令时完成。</p><p><strong>示例：</strong></p><p>下面的代码放在Host侧CMakeLists.txt中。调用前，需已通过<code>npu_op_package</code>创建<code>\${package_name}</code>算子包（<code>TYPE RUN</code>），并通过<code>npu_op_code_gen</code>在<code>\${ASCEND_AUTOGEN_PATH}</code>中生成代码；<code>\${ops_srcs}</code>为参与代码生成的Host侧源码列表。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c"># 配置aclnn单算子调用库，使用默认库名cust_opapi</span>
<span class="nb">file</span><span class="p">(</span><span class="s">GLOB</span><span class="w"> </span><span class="s">autogen_aclnn_src</span><span class="w"> </span><span class="o">\${</span><span class="nv">ASCEND_AUTOGEN_PATH</span><span class="o">}</span><span class="s">/aclnn_*.cpp</span><span class="p">)</span>
<span class="nb">set_source_files_properties</span><span class="p">(</span><span class="o">\${</span><span class="nv">autogen_aclnn_src</span><span class="o">}</span><span class="w"> </span><span class="s">PROPERTIES</span><span class="w"> </span><span class="s">GENERATED</span><span class="w"> </span><span class="s">TRUE</span><span class="p">)</span>
<span class="nb">npu_op_library</span><span class="p">(</span><span class="s">cust_opapi</span><span class="w"> </span><span class="s">ACLNN</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">autogen_aclnn_src</span><span class="o">}</span>
<span class="p">)</span>

<span class="c"># 配置算子原型库，入图场景需要，使用默认库名cust_opsproto_rt2.0</span>
<span class="nb">file</span><span class="p">(</span><span class="s">GLOB</span><span class="w"> </span><span class="s">proto_src</span><span class="w"> </span><span class="o">\${</span><span class="nv">ASCEND_AUTOGEN_PATH</span><span class="o">}</span><span class="s">/op_proto.cc</span><span class="p">)</span>
<span class="nb">set_source_files_properties</span><span class="p">(</span><span class="o">\${</span><span class="nv">proto_src</span><span class="o">}</span><span class="w"> </span><span class="s">PROPERTIES</span><span class="w"> </span><span class="s">GENERATED</span><span class="w"> </span><span class="s">TRUE</span><span class="p">)</span>
<span class="nb">npu_op_library</span><span class="p">(</span><span class="s">cust_op_proto</span><span class="w"> </span><span class="s">GRAPH</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">ops_srcs</span><span class="o">}</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">proto_src</span><span class="o">}</span>
<span class="p">)</span>

<span class="c"># 配置Tiling库，使用默认库名cust_opmaster_rt2.0</span>
<span class="nb">file</span><span class="p">(</span><span class="s">GLOB</span><span class="w"> </span><span class="s">fallback_src</span><span class="w"> </span><span class="o">\${</span><span class="nv">ASCEND_AUTOGEN_PATH</span><span class="o">}</span><span class="s">/fallback_*.cpp</span><span class="p">)</span>
<span class="nb">set_source_files_properties</span><span class="p">(</span><span class="o">\${</span><span class="nv">fallback_src</span><span class="o">}</span><span class="w"> </span><span class="s">PROPERTIES</span><span class="w"> </span><span class="s">GENERATED</span><span class="w"> </span><span class="s">TRUE</span><span class="p">)</span>
<span class="nb">npu_op_library</span><span class="p">(</span><span class="s">cust_optiling</span><span class="w"> </span><span class="s">TILING</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">ops_srcs</span><span class="o">}</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">fallback_src</span><span class="o">}</span>
<span class="p">)</span>

<span class="c"># 将上述目标加入算子包，并配置最终动态库的链接和安装</span>
<span class="nb">npu_op_package_add</span><span class="p">(</span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span>
<span class="w">    </span><span class="s">LIBRARY</span><span class="w"> </span><span class="s">cust_opapi</span><span class="w"> </span><span class="s">cust_op_proto</span><span class="w"> </span><span class="s">cust_optiling</span>
<span class="p">)</span>
</code></pre></div><p>如需将aclnn动态库命名为<code>libmy_opapi.so</code>，可将上例中的<code>npu_op_library(cust_opapi ACLNN ...)</code>替换为：</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_library</span><span class="p">(</span><span class="s">my_opapi</span><span class="w"> </span><span class="s">ACLNN</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">autogen_aclnn_src</span><span class="o">}</span>
<span class="w">    </span><span class="s">CONFIG</span><span class="w"> </span><span class="s">SET_OPAPI_NAME</span><span class="w"> </span><span class="s">True</span>
<span class="p">)</span>
</code></pre></div><p>同时，将<code>npu_op_package_add</code>中的<code>cust_opapi</code>改为<code>my_opapi</code>。<code>CONFIG</code>中的值是是否启用自定义库名的开关，实际库名由第一个参数<code>my_opapi</code>决定。</p><h3 id="npu_op_kernel_library">npu_op_kernel_library<a class="header-anchor" href="#npu_op_kernel_library">​</a></h3><p>配置核函数（Kernel）侧库，指定源码目录和依赖的Tiling库。调用后，还需通过<code>npu_op_package_add</code>将其加入package，才能生成相应的编译和打包任务。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_library</span><span class="p">(</span><span class="s">&lt;target_name&gt;</span><span class="w"> </span><span class="s">SRC_BASE</span><span class="w"> </span><span class="s">&lt;path&gt;</span><span class="w"> </span><span class="s">TILING_LIBRARY</span><span class="w"> </span><span class="s">&lt;tiling_target&gt;</span><span class="p">)</span>
</code></pre></div><p><strong>参数说明：</strong></p><ul><li><code>&lt;target_name&gt;</code>（必选）：目标的名称。</li><li><code>SRC_BASE &lt;path&gt;</code>（必选）：指定核函数（Kernel）源码的base目录，要求配置绝对路径。例如示例中的<code>op_kernel</code>目录的绝对路径。</li><li><code>TILING_LIBRARY &lt;tiling_target&gt;</code>（必选）：指定通过<code>npu_op_library(... TILING ...)</code>声明的Tiling目标。</li></ul><p><strong>示例：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_library</span><span class="p">(</span><span class="s">ascendc_kernels</span>
<span class="w">    </span><span class="s">SRC_BASE</span><span class="w"> </span><span class="o">\${</span><span class="nv">CMAKE_SOURCE_DIR</span><span class="o">}</span><span class="s">/op_kernel/</span>
<span class="w">    </span><span class="s">TILING_LIBRARY</span><span class="w"> </span><span class="s">cust_optiling</span>
<span class="p">)</span>
</code></pre></div><h3 id="npu_op_kernel_options">npu_op_kernel_options<a class="header-anchor" href="#npu_op_kernel_options">​</a></h3><p>添加核函数（Kernel）目标编译选项。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_options</span><span class="p">(</span><span class="s">&lt;target_name&gt;</span><span class="w"> </span><span class="s">&lt;op_type&gt;</span><span class="w"> </span><span class="s">[COMPUTE_UNIT</span><span class="w"> </span><span class="s">&lt;soc_version&gt;...</span><span class="w"> </span><span class="s">|</span><span class="w"> </span><span class="s">SOC_SERIES</span><span class="w"> </span><span class="s">&lt;series&gt;...]</span><span class="w"> </span><span class="s">OPTIONS</span><span class="w"> </span><span class="s">…</span><span class="p">)</span>
</code></pre></div><p><strong>参数说明：</strong></p><ul><li><code>&lt;target_name&gt;</code>（必选）：目标的名称。</li><li><code>&lt;op_type&gt;</code>（必选）：指定编译选项的生效范围。填写<code>ALL</code>表示对所有算子生效；填写具体的算子类型（如<code>AddCustom</code>）表示仅对该算子生效。</li><li><code>[COMPUTE_UNIT &lt;soc_version&gt;...]</code>（可选）：用于设置算子在具体AI处理器型号上的编译选项，不填写该选项时默认对所有型号生效。与<code>SOC_SERIES</code>不能同时使用。</li><li><code>[SOC_SERIES &lt;series&gt;...]</code>（可选）：用于按AI处理器系列设置编译选项。输入不区分大小写；与<code>COMPUTE_UNIT</code>不能同时使用。<code>SOC_SERIES</code>关键字后必须提供至少一个值；同一次调用同时提供<code>SOC_SERIES</code>和<code>COMPUTE_UNIT</code>，或只提供<code>SOC_SERIES</code>关键字不提供值，CMake配置阶段会报错。</li></ul><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明 其中，AI处理器型号<code>soc_version</code>请通过以下方式获取：</p><div data-filter="910b,910,310p,310b"><ul><li><p>针对如下产品：在安装AI处理器的服务器执行<code>npu-smi info</code>命令进行查询，获取Name信息。实际配置值为AscendName，例如Name取值为xxxyy，实际配置值为Ascendxxxyy。<br><br></p><div data-filter="910b"><p>Atlas A2系列产品</p></div><div data-filter="310b"><p>Atlas 200I/500 A2推理产品</p></div><div data-filter="310p"><p>Atlas推理系列产品</p></div><div data-filter="910"><p>Atlas训练系列产品<br><br></p></div></li></ul></div><div data-filter="A3"><ul><li>针对Atlas A3系列产品，在安装AI处理器的服务器执行<code>npu-smi info -t board -i &lt;id&gt; -c &lt;chip_id&gt;</code>命令进行查询，获取Chip Name和NPU Name信息，实际配置值为<code>Chip Name_NPU Name</code>。例如Chip Name取值为Ascendxxx，NPU Name取值为1234，实际配置值为Ascendxxx_1234。其中：<br><code>id</code>：设备id，通过<code>npu-smi info -l</code>命令查出的NPU ID即为设备id，命令中表示为<code>&lt;id&gt;</code>。<br><code>chip_id</code>：芯片id，通过<code>npu-smi info -m</code>命令查出的Chip ID即为芯片id，命令中表示为<code>&lt;chip_id&gt;</code>。<br><br></li></ul></div><div data-filter="950"><ul><li>针对Ascend 950PR&amp;950DT系列产品，在安装AI处理器的服务器执行<code>npu-smi info -t board -i &lt;id&gt;</code>命令进行查询，获取Chip Name和NPU Name信息，实际配置值为<code>Chip Name_NPU Name</code>。例如Chip Name取值为Ascendxxx，NPU Name取值为1234，实际配置值为Ascendxxx_1234。<br>其中：<code>id</code>为设备id，通过<code>npu-smi info -l</code>命令查出的NPU ID即为设备id，命令中表示为<code>&lt;id&gt;</code>。</li></ul></div></div><ul><li><code>OPTIONS …</code>（必选）：核函数编译选项，至少提供一个值。普通选项传给编译器；<code>--save-temp-files</code>、<code>--tiling_key</code>、<code>--kernel-template-input</code>等选项由构建脚本转换为对应的编译配置。 <ul><li><code>--cce-auto-sync</code>：开启毕昇编译器自动同步，由编译器自动插入部分同步指令。自定义算子开发工程默认开启auto-sync（<code>--cce-auto-sync=on</code>），无需重复设置；可通过<code>--cce-auto-sync=off</code>关闭。</li><li><code>--cce-auto-sync-log=&lt;file&gt;</code>：将编译器自动插入同步指令的信息输出到指定文件。需同时设置<code>-g</code>，以获取对应的源码行号。</li></ul></li></ul><p><strong>示例：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_options</span><span class="p">(</span><span class="s">ascendc_kernels</span><span class="w"> </span><span class="s">ALL</span><span class="w"> </span><span class="s">OPTIONS</span><span class="w"> </span><span class="s">--save-temp-files</span><span class="w"> </span><span class="s">-g</span><span class="p">)</span><span class="w">   </span><span class="c">#为算子添加编译选项</span>

<span class="nb">npu_op_kernel_options</span><span class="p">(</span><span class="s">ascendc_kernels</span><span class="w"> </span><span class="s">AddCustom</span><span class="w"> </span><span class="s">SOC_SERIES</span><span class="w"> </span><span class="s">Ascendxxx</span><span class="w"> </span><span class="s">Ascendyyy</span><span class="w"> </span><span class="s">OPTIONS</span><span class="w"> </span><span class="s">-DASCENDC_DEBUG</span><span class="p">)</span>
</code></pre></div><p>下面以AddCustom为例，将自动同步日志输出到构建目录下的<code>add_custom_auto_sync.log</code>。工程默认已开启auto-sync，因此只需添加日志选项和<code>-g</code>：</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_options</span><span class="p">(</span><span class="s">ascendc_kernels</span><span class="w"> </span><span class="s">AddCustom</span>
<span class="w">    </span><span class="s">OPTIONS</span><span class="w"> </span><span class="s">-g</span><span class="w"> </span><span class="s2">&quot;--cce-auto-sync-log=\${CMAKE_CURRENT_BINARY_DIR}/add_custom_auto_sync.log&quot;</span>
<span class="p">)</span>
</code></pre></div><h3 id="npu_op_kernel_sources">npu_op_kernel_sources<a class="header-anchor" href="#npu_op_kernel_sources">​</a></h3><p>描述核函数（Kernel）目标的源码信息，包括设置算子的核函数（Kernel）实现文件和源码路径等。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_sources</span><span class="p">(</span><span class="s">&lt;target_name&gt;</span><span class="w"> </span><span class="s">[OP_TYPE</span><span class="w"> </span><span class="s">&lt;op_type&gt;]</span><span class="w"> </span><span class="s">[KERNEL_DIR</span><span class="w"> </span><span class="s">&lt;path&gt;]</span><span class="w"> </span><span class="s">[COMPUTE_UNIT</span><span class="w"> </span><span class="s">&lt;soc_version&gt;...</span><span class="w"> </span><span class="s">|</span><span class="w"> </span><span class="s">SOC_SERIES</span><span class="w"> </span><span class="s">&lt;series&gt;...]</span><span class="w"> </span><span class="s">[KERNEL_FILE</span><span class="w"> </span><span class="s">&lt;file&gt;]</span><span class="p">)</span>
</code></pre></div><p><strong>参数说明：</strong></p><ul><li><code>&lt;target_name&gt;</code>（必选）：目标的名称。</li><li><code>[OP_TYPE &lt;op_type&gt;]</code>（可选）：算子类型，必须与<code>KERNEL_FILE</code>同时存在。不指定时，配置对所有算子生效。</li><li><code>[KERNEL_DIR &lt;path&gt;]</code>（可选）：指定核函数（Kernel）源码相对于<code>SRC_BASE</code>的相对路径。若算子的源码文件没有平铺在<code>SRC_BASE</code>目录（通过<code>npu_op_kernel_library</code>设置）下，可以通过<code>KERNEL_DIR</code>指定特定目录。</li><li><code>[COMPUTE_UNIT &lt;soc_version&gt;...]</code>（可选）：设置<code>KERNEL_FILE</code>在指定型号生效。默认<code>KERNEL_FILE</code>对所有型号生效。与<code>SOC_SERIES</code>不能同时使用。</li><li><code>[SOC_SERIES &lt;series&gt;...]</code>（可选）：设置<code>KERNEL_FILE</code>在指定系列生效。输入不区分大小写；与<code>COMPUTE_UNIT</code>不能同时使用，<code>SOC_SERIES</code>关键字后必须提供至少一个值；同一次调用同时提供<code>SOC_SERIES</code>和<code>COMPUTE_UNIT</code>，或只提供<code>SOC_SERIES</code>关键字不提供值，CMake配置阶段会报错。</li><li><code>[KERNEL_FILE &lt;file&gt;]</code>（可选）：指定算子入口的核函数（Kernel）实现文件名。若算子的核函数（Kernel）实现cpp文件需要自定义命名，需同时指定<code>OP_TYPE</code>（算子类型）和<code>KERNEL_FILE</code>（核函数（Kernel）实现cpp文件名），以配置两者之间的对应关系。不配置时，核函数（Kernel）实现cpp文件名和OpType之间需满足转换规则，参考<a href="./naming_conversion_table.html">命名转换规则对照表</a>。</li></ul><p><strong>示例：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_sources</span><span class="p">(</span><span class="s">ascendc_kernels</span>
<span class="w">    </span><span class="s">OP_TYPE</span><span class="w"> </span><span class="s">AddCustom</span>
<span class="w">    </span><span class="s">KERNEL_DIR</span><span class="w"> </span><span class="s">./Add</span>
<span class="w">    </span><span class="s">COMPUTE_UNIT</span><span class="w"> </span><span class="s">Ascendxxxyy</span>
<span class="w">    </span><span class="s">KERNEL_FILE</span><span class="w"> </span><span class="s">add_custom.cpp</span>
<span class="p">)</span>
</code></pre></div><p>也可以使用<code>SOC_SERIES</code>按系列指定：</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_sources</span><span class="p">(</span><span class="s">ascendc_kernels</span>
<span class="w">    </span><span class="s">OP_TYPE</span><span class="w"> </span><span class="s">AddCustom</span>
<span class="w">    </span><span class="s">KERNEL_DIR</span><span class="w"> </span><span class="s">./Add</span>
<span class="w">    </span><span class="s">SOC_SERIES</span><span class="w"> </span><span class="s">Ascendxxx</span>
<span class="w">    </span><span class="s">KERNEL_FILE</span><span class="w"> </span><span class="s">add_custom.cpp</span>
<span class="p">)</span>
</code></pre></div><p>如果同一算子在不同AI处理器系列上需要不同的核函数（Kernel）实现，可多次调用<code>npu_op_kernel_sources</code>，分别用<code>SOC_SERIES</code>指定各自生效的范围：</p><p>以下<code>ascendxxx1</code>、<code>ascendxxx2</code>和<code>ascendxxx3</code>为不同AI处理器系列的构建目标占位符，请替换为实际取值。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_sources</span><span class="p">(</span><span class="s">ascendc_kernels</span>
<span class="w">    </span><span class="s">OP_TYPE</span><span class="w"> </span><span class="s">AddCustom</span>
<span class="w">    </span><span class="s">SOC_SERIES</span><span class="w"> </span><span class="s">ascendxxx1</span><span class="w"> </span><span class="s">ascendxxx2</span>
<span class="w">    </span><span class="s">KERNEL_FILE</span><span class="w"> </span><span class="s">add_custom_v220.cpp</span>
<span class="p">)</span>
<span class="nb">npu_op_kernel_sources</span><span class="p">(</span><span class="s">ascendc_kernels</span>
<span class="w">    </span><span class="s">OP_TYPE</span><span class="w"> </span><span class="s">AddCustom</span>
<span class="w">    </span><span class="s">SOC_SERIES</span><span class="w"> </span><span class="s">ascendxxx3</span>
<span class="w">    </span><span class="s">KERNEL_FILE</span><span class="w"> </span><span class="s">add_custom_v310.cpp</span>
<span class="p">)</span>
</code></pre></div><h3 id="npu_op_device_tiling_library">npu_op_device_tiling_library<a class="header-anchor" href="#npu_op_device_tiling_library">​</a></h3><p>创建用于Tiling下沉的Device侧Tiling库。创建后，需通过<code>npu_op_package_add</code>将其加入package，package的类型仅支持<code>RUN</code>（run包模式）。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_device_tiling_library</span><span class="p">(</span><span class="s">&lt;target_name&gt;</span><span class="w"> </span><span class="s">&lt;type&gt;</span><span class="w"> </span><span class="s">&lt;files&gt;</span><span class="p">)</span>
</code></pre></div><p><strong>参数说明：</strong></p><ul><li><code>&lt;target_name&gt;</code>（必选）：目标的名称。</li><li><code>&lt;type&gt;</code>（必选）：指定Tiling产物的类型。支持取值为<code>SHARED</code>、<code>STATIC</code>。</li><li><code>&lt;files&gt;</code>（必选）：指定Tiling源码文件。</li></ul><p><strong>示例：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_device_tiling_library</span><span class="p">(</span><span class="s">device_tiling</span><span class="w"> </span><span class="s">SHARED</span>
<span class="w">    </span><span class="s">device_tiling_impl.cpp</span>
<span class="p">)</span>
<span class="nb">npu_op_package_add</span><span class="p">(</span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span><span class="w"> </span><span class="s">LIBRARY</span><span class="w"> </span><span class="s">device_tiling</span><span class="p">)</span>
</code></pre></div><hr><h2 id="其他">其他<a class="header-anchor" href="#其他">​</a></h2><h3 id="npu_op_code_gen">npu_op_code_gen<a class="header-anchor" href="#npu_op_code_gen">​</a></h3><p>执行代码生成过程，生成aclnn单算子调用代码和入图所需的原型定义代码。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_code_gen</span><span class="p">(</span><span class="s">SRC</span><span class="w"> </span><span class="s">&lt;src_files&gt;...</span>
<span class="w">    </span><span class="s">OUT_DIR</span><span class="w"> </span><span class="s">&lt;output_dir&gt;</span>
<span class="w">    </span><span class="s">PACKAGE</span><span class="w"> </span><span class="s">&lt;pkg_name&gt;</span>
<span class="w">    </span><span class="s">[COMPILE_OPTIONS</span><span class="w"> </span><span class="s">&lt;options&gt;...]</span>
<span class="w">    </span><span class="s">[LINK_OPTIONS</span><span class="w"> </span><span class="s">&lt;options&gt;...]</span>
<span class="w">    </span><span class="s">[JOBS</span><span class="w"> </span><span class="s">&lt;count&gt;]</span>
<span class="w">    </span><span class="s">[JOIN_OP_DEF</span><span class="w"> </span><span class="s">&lt;True|False&gt;]</span>
<span class="w">    </span><span class="s">[OPTIONS</span><span class="w"> </span><span class="s">&lt;key&gt;</span><span class="w"> </span><span class="s">&lt;value&gt;</span><span class="w"> </span><span class="s">...]</span>
<span class="p">)</span>
</code></pre></div><p><strong>参数说明：</strong></p><ul><li><p><code>SRC &lt;src_files&gt;</code>（必选）：参与代码生成的源文件范围。</p></li><li><p><code>OUT_DIR &lt;output_dir&gt;</code>（必选）：生成代码的输出路径。</p></li><li><p><code>PACKAGE &lt;pkg_name&gt;</code>（必选）：指定生成代码的package名称。</p></li><li><p><code>COMPILE_OPTIONS &lt;options&gt;...</code>（可选）：设置Host侧原型代码的编译选项，用于生成<code>libascend_all_ops.so</code>。核函数编译选项请通过<code>npu_op_kernel_options</code>设置。</p></li><li><p><code>LINK_OPTIONS &lt;options&gt;...</code>（可选）：设置生成<code>libascend_all_ops.so</code>时的链接选项。</p></li><li><p><code>JOBS &lt;count&gt;</code>（可选）：设置Host侧原型代码的编译并行数，必须为正整数。</p></li><li><p><code>JOIN_OP_DEF &lt;True|False&gt;</code>（可选）：设置生成型号配置的方式，默认为<code>False</code>。参数值区分大小写，仅支持<code>True</code>和<code>False</code>；其他值会产生警告，并按<code>False</code>处理。</p><ul><li><code>False</code>：根据工程中<code>ASCEND_SOC_SERIES</code>或<code>ASCEND_COMPUTE_UNIT</code>指定的构建目标生成型号配置。</li><li><code>True</code>：根据算子原型中<code>AddConfig</code>注册的型号生成配置。后续仍按工程指定的目标编译核函数，因此<code>AddConfig</code>需覆盖这些目标。</li></ul><p>该参数与是否使用<code>CMakePresets.json</code>无关，也不会改变工程的构建目标。</p></li><li><p><code>OPTIONS &lt;key&gt; &lt;value&gt; ...</code>（可选）：设置opbuild的代码生成选项，各选项以“参数名 参数值”的形式提供：</p><ul><li><code>OPS_PROJECT_NAME</code>：设置生成代码的项目名称。</li><li><code>OPS_DIRECT_ACCESS_PREFIX</code>：设置直接调用接口的名称前缀。</li><li><code>OPS_ACLNN_GEN</code>：控制是否生成aclnn代码。</li><li><code>OPS_ENABLE_SOURCE_PACKAGE</code>：设置源码发布配置。</li><li><code>OPS_VENDOR_NAME</code>：设置代码生成使用的厂商名称。</li><li><code>OPS_PROTO_SEPARATE</code>：控制是否按算子分别生成原型文件。</li></ul></li></ul><p>该函数在执行<code>cmake</code>配置工程时生成代码，包括aclnn调用代码、原型定义、Tiling辅助代码和型号配置等。请先创建package，再调用本函数；代码生成完成后，才能使用生成的文件，以及<code>npu_op_kernel_options</code>、<code>npu_op_kernel_sources</code>和<code>npu_op_kernel_library</code>。</p><p><strong>示例：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">aux_source_directory</span><span class="p">(</span><span class="o">\${</span><span class="nv">CMAKE_CURRENT_SOURCE_DIR</span><span class="o">}</span><span class="w"> </span><span class="s">ops_srcs</span><span class="p">)</span>
<span class="nb">npu_op_code_gen</span><span class="p">(</span>
<span class="w">    </span><span class="s">SRC</span><span class="w"> </span><span class="o">\${</span><span class="nv">ops_srcs</span><span class="o">}</span>
<span class="w">    </span><span class="s">PACKAGE</span><span class="w"> </span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span>
<span class="w">    </span><span class="s">COMPILE_OPTIONS</span><span class="w"> </span><span class="s">-g</span>
<span class="w">    </span><span class="s">OUT_DIR</span><span class="w"> </span><span class="o">\${</span><span class="nv">ASCEND_AUTOGEN_PATH</span><span class="o">}</span>
<span class="w">    </span><span class="s">JOIN_OP_DEF</span><span class="w"> </span><span class="s">False</span>
<span class="p">)</span>
</code></pre></div><hr><h2 id="相关文档">相关文档<a class="header-anchor" href="#相关文档">​</a></h2><ul><li><a href="../compilation_and_deployment/basic_process.html#advanced-build-organization">算子工程编译拓展</a> — 完整的CMakeLists.txt编写方法与编译命令说明。</li><li><a href="../design_and_implementation/operator_prototype_definition.html">算子原型定义</a> — 核函数（Kernel）实现文件名与OpType的转换规则。</li><li><a href="../../../appendix/common_operations/how_to_use_workspace.html">如何使用workspace</a> — Tiling函数中workspace的设置方法。</li></ul></article></div>`,1)])])}const g=a(e,[["render",l]]);export{h as __pageData,g as default};
